// src/components/App.js

import React from 'react';
import TonalitySelector from './TonalitySelector';
import SettingsPanel from './SettingsPanel';
import OutputDisplay from './OutputDisplay';
import useChordGenerator from '../hooks/useChordGenerator';
import { keyPairs } from '../data/vocabulary';

function App() {
  // Вызываем хук и деструктурируем свойства с помощью опциональной цепочки
  const { state, sequence, handleInput, chordDiagrams, keySignatures } = useChordGenerator();

  // Проверяем, готов ли хук.
  // Если 'state' или 'sequence' не определены, возвращаем null (ничего не рендерим).
  if (state === undefined || sequence === undefined) {
    return null; // Или можно показать лоадер <div>Загрузка...</div>
  }

  // --- БЛОК ВСТУПИТЕЛЬНОГО ТЕКСТА И КНОПОК ---
  // Этот блок показывается, если последовательности НЕТ
  if (sequence.length === 0) {
    return (
      <div className="min-h-screen bg-gray-900 text-white p-8">
        <div className="space-y-8">
          <h1 className="text-3xl font-bold mb-4 text-center">Генератор аккордов</h1>
          <p className="text-lg mt-10 text-center">
            Нажмите кнопку для генерации или выберите тональность из таблицы.
          </p>
          <div className="flex flex-col sm:flex-row justify-center gap-3 mb-8">
            <button
              onClick={() => handleInput('0')}
              className="w-full sm:w-auto bg-gray-700 hover:bg-gray-600 text-white font-medium py-2 px-4 rounded"
            >
              🎲 Случайная тональность
            </button>
            <button
              onClick={() => handleInput('00')}
              className="w-full sm:w-auto bg-green-600 hover:bg-green-700 text-white font-medium py-2 px-4 rounded"
            >
              ⚡️ Быстрая генерация
            </button>
          </div>
          <TonalitySelector keyPairs={keyPairs} onSelect={handleInput} keySignatures={keySignatures} />
        </div>
      </div>
    );
  }

  // --- БЛОК РЕЗУЛЬТАТА ---
  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <div className="grid md:grid-cols-2 gap-8">
        <div>
          <h2 className="text-xl font-semibold mb-2">Настройки</h2>
          <SettingsPanel onChange={handleInput} />
        </div>
        <div>
          <h2 className="text-xl font-semibold mb-2">Ваша последовательность</h2>
          <OutputDisplay sequence={sequence} />
          <div className="space-y-2 mt-6">
            <button
              onClick={() => handleInput('generate')}
              className="w-full bg-blue-500 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded"
            >
              Сгенерировать снова ({sequenceLength})
            </button>
            <button
              onClick={() => handleInput('reset')}
              className="w-full bg-gray-700 hover:bg-gray-600 text-white font-medium py-2 px-4 rounded"
            >
              Начать заново / Выбрать тональность
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
